{"cards": [{"node_code": "N_086924bcb23dff0d", "definition": "研究船舶动力装置及机械系统所使用的各类润滑剂（如润滑油、润滑脂）的理化性质、分类、性能指标、选用原则及储存管理技术。", "boundary": "本节点聚焦于润滑剂作为“物质材料”本身的属性与应用。边界在于区分“润滑剂材料”与“润滑系统”：若内容涉及润滑油的粘度、闪点、抗磨性等指标及牌号选用，归入本节点；若涉及船舶润滑系统的结构设计、油路布置或运行维护管理，归入船舶工程或航海技术管理。", "includes": ["船舶用润滑油、润滑脂的种类、性能指标及选用原则", "润滑剂的理化性质、储存条件及质量控制", "润滑剂在船舶机械中的摩擦学基础与减摩原理"], "excludes": ["船舶润滑系统的结构设计与制造工艺（归入船舶工程）", "润滑系统的运行维护、油液监测及故障诊断（归入航海技术管理）"], "sibling_distinctions": [{"other_code": "N_ce0169f1f0540ca0", "rule": "本节点关注润滑剂基础油及成品的整体性能，兄弟节点关注用于改善燃料或润滑剂性能的特定化学添加剂。"}, {"other_code": "N_dcf04f1bbd168686", "rule": "本节点关注润滑介质，兄弟节点关注作为能源的液体燃料（如重油、柴油）。"}], "cross_boundary_rule": "若内容涉及润滑剂在特定工况下的摩擦磨损机理，主挂载本节点；若涉及润滑系统整体效率优化，可关联船舶工程。"}, {"node_code": "N_ce0169f1f0540ca0", "definition": "研究用于改善船舶燃料（如燃油）和润滑剂（如润滑油）性能的化学添加剂的作用机理、配方设计、质量控制及在船舶燃润料中的应用技术。", "boundary": "本节点聚焦于“添加剂”这一特定物质类别。边界在于区分“添加剂”与“基础燃料/润滑剂”：若内容涉及清净剂、分散剂、抗氧剂等添加剂的化学结构、复配技术及对燃润料性能的改善，归入本节点；若涉及燃料或润滑剂的整体理化性质，归入对应的燃料或润滑剂节点。", "includes": ["船舶燃油清净分散剂、抗氧剂、防锈剂等添加剂的作用机理", "船舶润滑油抗磨剂、极压剂、粘度指数改进剂等添加剂的配方", "燃润料添加剂的质量检测标准及在船舶燃润料中的复配应用"], "excludes": ["燃料或润滑剂基础油本身的理化性质（归入液体燃料或润滑剂节点）", "添加剂在发动机燃烧过程中的反应动力学（归入船舶工程）"], "sibling_distinctions": [{"other_code": "N_086924bcb23dff0d", "rule": "本节点关注用于改善性能的“添加剂”，兄弟节点关注润滑剂“基础油及成品”的整体属性。"}, {"other_code": "N_dcf04f1bbd168686", "rule": "本节点关注用于改善燃料性能的“添加剂”，兄弟节点关注“液体燃料”本身的性质与选用。"}], "cross_boundary_rule": "若内容涉及添加剂与基础油的相容性研究，主挂载本节点；若涉及添加剂对发动机寿命的影响评估，可关联航海技术管理。"}, {"node_code": "N_20a8244af318271f", "definition": "研究船舶动力装置所使用的各类气体燃料（如LNG、LPG、CNG、甲醇等）的理化性质、储存技术、安全规范及在船舶中的应用特性。", "boundary": "本节点聚焦于“气体”形态的船舶燃料。边界在于区分“气体燃料”与“液体/固体燃料”：若内容涉及LNG、LPG等气体燃料的低温储存、气化、输送及安全特性，归入本节点；若涉及重油、柴油等液体燃料，归入液体燃料节点；若涉及燃料在发动机中的燃烧过程，归入船舶工程。", "includes": ["LNG、LPG、CNG等气体燃料的理化性质、储存及气化技术", "气体燃料在船舶上的安全规范、泄漏检测及应急处置", "气体燃料与液体燃料的混合使用特性及转换技术"], "excludes": ["液体燃料（如重油、柴油）的性质与选用（归入液体燃料节点）", "气体燃料在发动机中的燃烧优化及排放控制（归入船舶工程）"], "sibling_distinctions": [{"other_code": "N_dcf04f1bbd168686", "rule": "本节点关注“气体”形态燃料，兄弟节点关注“液体”形态燃料（如重油、柴油）。"}, {"other_code": "N_056c76132362a5ee", "rule": "本节点关注“气体”形态燃料，兄弟节点关注“固体”形态燃料（如船用煤、生物质燃料）。"}], "cross_boundary_rule": "若内容涉及气体燃料的低温储罐设计，主挂载本节点；若涉及气体燃料发动机的结构改造，可关联船舶工程。"}]}
